<script setup lang="ts">
const { notify } = useAppToast()
const search = ref('')
const category = ref('ทั้งหมด')
const showModal = ref(false)
const productName = ref('')
const productPrice = ref('')
const categories = ['ทั้งหมด', 'ยางรถยนต์', 'บริการ', 'น้ำมันเครื่อง', 'อะไหล่']
const products = ref([
  { name: 'ยางรถยนต์ Premium Touring', sku: 'TYR-001 · 205/55R16', category: 'ยางรถยนต์', price: '4,290', stock: 28, state: 'พร้อมจำหน่าย', tone: 'tire-red' },
  { name: 'ยางรถยนต์ Comfort Ride', sku: 'TYR-002 · 195/65R15', category: 'ยางรถยนต์', price: '3,650', stock: 16, state: 'พร้อมจำหน่าย', tone: 'tire-blue' },
  { name: 'น้ำมันเครื่องสังเคราะห์ 5W-30', sku: 'OIL-015 · 4 ลิตร', category: 'น้ำมันเครื่อง', price: '1,590', stock: 42, state: 'พร้อมจำหน่าย', tone: 'oil' },
  { name: 'ตั้งศูนย์และถ่วงล้อ', sku: 'SRV-004 · ต่อคัน', category: 'บริการ', price: '800', stock: null, state: 'เปิดให้บริการ', tone: 'service' },
  { name: 'ผ้าเบรกหน้า Premium', sku: 'BRK-031 · 1 ชุด', category: 'อะไหล่', price: '2,450', stock: 7, state: 'ใกล้หมด', tone: 'parts' },
  { name: 'เช็กระยะ 10,000 กม.', sku: 'SRV-011 · แพ็กเกจ', category: 'บริการ', price: '1,200', stock: null, state: 'เปิดให้บริการ', tone: 'service' }
])
const filtered = computed(() => products.value.filter(p => (category.value === 'ทั้งหมด' || p.category === category.value) && `${p.name} ${p.sku}`.toLowerCase().includes(search.value.toLowerCase())))
function addProduct() {
  if (!productName.value.trim()) return notify('กรุณากรอกชื่อสินค้า / บริการ')
  products.value.unshift({ name: productName.value, sku: `NEW-${String(products.value.length + 1).padStart(3, '0')} · รายการใหม่`, category: category.value === 'ทั้งหมด' ? 'บริการ' : category.value, price: productPrice.value || '0', stock: 0, state: 'ร่าง', tone: 'service' })
  productName.value = ''; productPrice.value = ''; showModal.value = false; notify('เพิ่มรายการตัวอย่างแล้ว')
}
</script>

<template>
  <div class="page-heading"><div><div class="eyebrow">CATALOG MANAGEMENT</div><h1>สินค้าและบริการ</h1><p>จัดการรายการสินค้า ราคา และบริการของสาขา</p></div><div class="heading-actions"><button class="btn btn-light" @click="notify('นำเข้ารายการสินค้าในระบบจริงได้')"><AppIcon name="download" :size="15" />นำเข้ารายการ</button><button class="btn btn-primary" @click="showModal = true"><AppIcon name="plus" :size="16" />เพิ่มสินค้า</button></div></div>

  <div class="catalog-overview"><div class="catalog-stat"><span class="catalog-icon red"><AppIcon name="box" :size="17" /></span><div><small>รายการทั้งหมด</small><strong>148</strong></div></div><div class="catalog-stat"><span class="catalog-icon green"><AppIcon name="check" :size="17" /></span><div><small>พร้อมขาย / ให้บริการ</small><strong>132</strong></div></div><div class="catalog-stat"><span class="catalog-icon amber"><AppIcon name="clock" :size="17" /></span><div><small>สินค้าใกล้หมด</small><strong>7</strong></div></div><div class="stock-meter"><div><span>ความพร้อมของสต็อก</span><b>84%</b></div><div class="meter-track"><i /></div><small>อัปเดตล่าสุดวันนี้ 09:15 น.</small></div></div>

  <section class="panel catalog-panel">
    <div class="catalog-toolbar"><div class="category-tabs"><button v-for="c in categories" :key="c" :class="{ active: category === c }" @click="category = c">{{ c }} <small v-if="c === 'ทั้งหมด'">148</small></button></div><div class="catalog-actions"><label class="search-field"><AppIcon name="search" :size="16" /><input v-model="search" placeholder="ค้นหาสินค้า..." /></label><button class="icon-button" aria-label="ตัวกรอง" @click="notify('ตัวกรองเพิ่มเติมในระบบจริง')"><AppIcon name="filter" :size="16" /></button></div></div>
    <div class="product-grid">
      <article v-for="p in filtered" :key="p.sku" class="product-card">
        <div class="product-visual" :class="p.tone"><div v-if="p.tone.startsWith('tire')" class="tire-shape"><span /></div><div v-else-if="p.tone === 'oil'" class="oil-shape"><i>LC</i></div><div v-else class="service-shape"><AppIcon :name="p.tone === 'parts' ? 'car' : 'carWheel'" :size="36" /></div><button class="product-more" aria-label="เมนูสินค้า" @click="notify(`เมนูจัดการ ${p.name}`)"><AppIcon name="more" :size="17" /></button><span class="category-chip">{{ p.category }}</span></div>
        <div class="product-info"><div class="product-name-row"><h3>{{ p.name }}</h3><button class="edit-product" aria-label="แก้ไข" @click="notify('แก้ไขรายการในระบบจริงได้')"><AppIcon name="edit" :size="14" /></button></div><small class="product-sku">{{ p.sku }}</small><div class="product-bottom"><div><small>ราคาเริ่มต้น</small><strong>฿{{ p.price }}</strong></div><span v-if="p.stock !== null" class="stock-state" :class="p.stock < 10 ? 'low' : ''"><i />{{ p.stock < 10 ? 'เหลือ ' + p.stock : 'สต็อก ' + p.stock }}</span><span v-else class="stock-state service-state"><i />{{ p.state }}</span></div></div>
      </article>
      <div v-if="!filtered.length" class="empty-state"><AppIcon name="search" :size="23"/><strong>ไม่พบรายการ</strong><p>ลองค้นหาด้วยชื่อสินค้าอื่น</p></div>
    </div>
    <div class="catalog-footer"><span>แสดง {{ filtered.length }} รายการตัวอย่าง</span><button class="btn btn-light btn-sm" @click="notify('โหลดรายการสินค้าเพิ่มเติมเมื่อเชื่อม MySQL')">ดูรายการทั้งหมด <AppIcon name="arrowRight" :size="13" /></button></div>
  </section>

  <div v-if="showModal" class="modal-backdrop" @click.self="showModal = false"><div class="modal-card"><div class="modal-head"><div><h3>เพิ่มสินค้า / บริการ</h3><p>สร้างรายการใหม่ในแค็ตตาล็อก</p></div><button class="modal-close" @click="showModal = false"><AppIcon name="close" :size="16" /></button></div><div class="modal-content"><div class="field"><label class="form-label">ชื่อรายการ <span class="required">*</span></label><input v-model="productName" class="form-control" placeholder="ระบุชื่อสินค้า / บริการ" /></div><div class="field"><label class="form-label">หมวดหมู่</label><select v-model="category" class="form-control"><option v-for="c in categories.slice(1)" :key="c">{{ c }}</option></select></div><div class="field"><label class="form-label">ราคาเริ่มต้น (บาท)</label><input v-model="productPrice" class="form-control" inputmode="decimal" placeholder="0.00" /></div></div><div class="modal-footer"><button class="btn btn-light" @click="showModal = false">ยกเลิก</button><button class="btn btn-primary" @click="addProduct">บันทึกรายการ</button></div></div></div>
</template>

